\caption{Computing a greedy path \label{alg:InnerMaxLoop}}

\KwIn{Oracles for the value of a function $f: \mathbb{R}^d \times \mathbb{R}^d \rightarrow \mathbb{R}$, the gradient $\nabla_yf$ and the Hessian $\nabla_y^2f$}

\KwIn{$\mathsf{x}, \mathsf{y}^0, \varepsilon'$} 

\KwHyperparameters{$\delta, \mu_1, \mu_3, \mu_4$}

Set $\ell \leftarrow 0$,  $\mathsf{Stopy}  \leftarrow \textrm{False}$

\While{$\mathsf{Stopy} = \mathsf{False}$}{ \label{InnerWhileStart}

\uIf{$\| \nabla_yf(\mathsf{x}, \mathsf{y}^{\ell})\| > \varepsilon'$}{ \label{NoislessSGD_Start}

 Set $\mathsf{y}^{\ell+1} \leftarrow \mathsf{y}^{\ell} + \mu_1 \nabla_yf(\mathsf{x},\mathsf{y}^{\ell})$ \label{SGD_NoNoise} 

   Set $\ell \leftarrow \ell+1$} \label{NoislessSGD_End}

\Else{

Compute an eigenvalue-eigenvector pair $(\lambda, v)$ of $\nabla^2_{{y}}f(\mathsf{x}, \mathsf{y}^{\ell})$, s.t. $\lambda \geq \lambda_{\mathrm{max}}(\nabla^2_{{y}}f(\mathsf{x}, \mathsf{y}^{\ell})) - \mu_4$ \label{Compute_eigenvalue} 

\uIf{$\lambda > \sqrt{L_{} \varepsilon'}$}{  \label{GreedyEnpoint_Start}

Set $\mathsf{a} = \mathrm{sign}(\nabla_yf(\mathsf{x},\mathsf{y}^{\ell})^\top v)$

Set $\mathsf{y}^{\ell+1} \leftarrow \mathsf{y}^\ell + \mu_3  \mathsf{a} v$  \label{saddle_escape}

 Set $\ell \leftarrow \ell+1$  


\Else{Set $\mathsf{Stopy} = \mathsf{True}$}}

\label{GreedyEnpoint_End}

}

\label{InnerWhileEnd}}

\Return{$\mathsf{y}_{\mathrm{LocalMax}} \leftarrow \mathsf{y}^{\ell}$}

